mapper.select:
select t.log_id logId, t.biz_type bizType, t.biz_id bizId, t.step step, t.result result,
t.opinion opinion, t.auditor_id auditorId, t.auditor_name auditorName, t.audit_time auditTime,
t.store_id storeId, t.status_cd statusCd, t.create_time createTime
from contract_audit_log t
where 1 = 1

    and t.log_id = #{logId}


    and t.biz_type = #{bizType}


    and t.biz_id = #{bizId}


    and t.biz_id in

        #{item}



    and t.step = #{step}


    and t.result = #{result}


    and t.auditor_id = #{auditorId}


    and t.store_id = #{storeId}


    and t.status_cd = #{statusCd}

order by t.audit_time asc

    limit #{page}, #{row}

select count(1) count
from contract_audit_log t
where 1 = 1

    and t.biz_type = #{bizType}


    and t.biz_id = #{bizId}


    and t.biz_id in

        #{item}



    and t.step = #{step}


    and t.result = #{result}


    and t.auditor_id = #{auditorId}


    and t.store_id = #{storeId}


    and t.status_cd = #{statusCd}
